repo_files.mailbox.py:
"""Actor message mailbox with priority queue."""

from typing import List, Optional
from message import ActorMessage


class Mailbox:
    def __init__(self):
        self.messages: List[ActorMessage] = []

    def enqueue(self, msg: ActorMessage) -> None:
        # Responses to ask requests get priority
        if msg.correlation_id:
            self.messages.insert(0, msg)
        else:
            self.messages.append(msg)

    def dequeue(self) -> Optional[ActorMessage]:
        return self.messages.pop(0) if self.messages else None

