"""Actor reference and message dispatch."""

from typing import Any, Callable, Dict, Optional
from mailbox import Mailbox
from message import ActorMessage


class ActorRef:
    def __init__(self, name: str, handler: Callable[[ActorMessage], Any]):
        self.name = name
        self.handler = handler
        self.mailbox = Mailbox()
        self.system_registry: Dict[str, "ActorRef"] = {}

    def tell(self, target: "ActorRef", payload: Any) -> None:
        msg = ActorMessage(sender=self.name, target=target.name, payload=payload)
        target.mailbox.enqueue(msg)

    def process_one(self) -> bool:
        msg = self.mailbox.dequeue()
        if not msg:
            return False
        res = self.handler(msg)
        if msg.is_ask and msg.correlation_id and msg.sender:
            sender_ref = self.system_registry.get(msg.sender)
            if sender_ref:
                reply = ActorMessage(sender=self.name, target=msg.sender, payload=res, correlation_id=msg.correlation_id)
                sender_ref.mailbox.enqueue(reply)
        return True
